import json,glob,os
def strip(x):
    if isinstance(x,dict): return {k:({"sha256":"x"*64,"bytes":len(v)} if k=="base64" and isinstance(v,str) else strip(v)) for k,v in x.items()}
    if isinstance(x,list): return [strip(i) for i in x]
    return x
for f in sorted(glob.glob('research/ai-log/raw/*.jsonl')):
    tot=os.path.getsize(f); new=0; big=0
    for l in open(f):
        try: d=json.loads(l)
        except: continue
        s=len(json.dumps(strip(d),ensure_ascii=False))+1; new+=s
        if s>65536: big+=s
    print(os.path.basename(f)[:45], round(tot/1e6,1),'->',round(new/1e6,1),'MB; entries>64KB after:',round(big/1e6,1),'MB')
EOF

